<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class AdminUserController extends Controller { public function index(){return view('admin.admin-users',['admins'=>User::where('is_admin',true)->orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users,email','password'=>'required|string|min:8','admin_role'=>'required|in:owner,manager,staff']);User::create(['name'=>$d['name'],'email'=>$d['email'],'password'=>Hash::make($d['password']),'is_admin'=>true,'admin_role'=>$d['admin_role']]);return back()->with('success','Admin user created.');} public function update(Request $r,User $user){abort_unless($user->is_admin,404);$d=$r->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users,email,'.$user->id,'password'=>'nullable|string|min:8','admin_role'=>'required|in:owner,manager,staff']);if(empty($d['password']))unset($d['password']);else $d['password']=Hash::make($d['password']);$user->update($d);return back()->with('success','Admin updated.');} public function destroy(User $user){abort_if($user->id===auth()->id(),422,'You cannot delete yourself.');abort_if($user->admin_role==='owner'&&User::where('is_admin',true)->where('admin_role','owner')->count()<=1,422,'Keep at least one owner.');$user->delete();return back()->with('success','Admin removed.');} }
